        "explain": "怎样的一生是值得的？能够活出自己的人生，自食其力，实现自我价值，这样的一生是值得的；当别人需要帮助时，付出自己的爱心，无论大小，自愿承担责任，这样的一生是值得的；能够将个人理想与国家发展、民族复兴和人类命运共同体结合起来，这样的一生是值得的。"
