      "type": "choice",
      "raw": {
        "source": "改编自深圳中考（综合探究情境型）",
        "q": "情境：感动中国人物张桂梅，创办了全国第一所全免费女子高中，帮助上千名山区女孩圆了大学梦。她身患多种疾病，却始终坚守在教育一线。有人说她傻，有人说她伟大。\n\n从生命价值的角度，你认为张桂梅校长的人生：",
        "options": [
          "确实傻，不值得，牺牲太大了",
          "是伟大的。伟大在于创造和贡献。她用自己的品德、才智和劳动，创造出了不平凡的社会价值",
          "她是校长，这是她应该做的，没什么伟大的",
          "只有做出惊天动地的大事才叫伟大，她做的都是小事"
        ],
        "answer": 1,
        "explain": "伟大在于创造和贡献。一个人的伟大，不在于其地位的高低，而在于他能够运用自身的品德、才智和劳动，创造出比自己有限的生命更长久的、不平凡的社会价值，为我们留下宝贵的物质财富和精神财富，影响着一代又一代的人。张桂梅校长在平凡的岗位上做出了不平凡的贡献，她的人生是伟大的。"
      },
