        "source": "改编自广东中考真题（材料型）",
        "material": "材料：感动中国人物张桂梅，创办了全国第一所全免费女子高中，帮助上千名山区女孩圆了大学梦。她身患多种疾病，却始终坚守在教育一线。有人问她为什么这么拼，她说：「我想让山区的女孩们走出大山，改变命运。」「一个女孩可以影响三代人。」",
